function fvPrincipal(P,r,years,n){ if(!(n>0)) n=1; return P*Math.pow(1+r/n, n*years); }
function fvAnnuity(pmt,r,years,n){ if(!(n>0)) n=1; if(r===0) return pmt*years*n;
  var g=Math.pow(1+r/n, n*years); return pmt*(g-1)/(r/n); }
function compound(P,r,years,n,pmt){
  P=+P||0; r=+r||0; years=+years||0; n=+n||0; pmt=+pmt||0;
  var principal=fvPrincipal(P,r,years,n);
  var ann=fvAnnuity(pmt,r,years,n);
  var total=principal+ann;
  var contrib=pmt*years*(n>0?n:1);
  return {futureValue:total, contributions:contrib, interest:total-P-contrib, principalGrowth:principal-P};
}
var EXPORTS={fvPrincipal:fvPrincipal, fvAnnuity:fvAnnuity, compound:compound};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CompoundForgePure = EXPORTS; }
